mapper.insert:
INSERT /*+ append */ INTO ${newTableName}
SELECT /*+ parallel(INFO,8) */ INFO.* from CHB_INVESTHOLD_INFO INFO
WHERE info.HOLD_DATE BETWEEN TO_DATE(#{startDate,jdbcType=VARCHAR},'yyyy-MM-dd') AND TO_DATE(#{endDate,jdbcType=VARCHAR},'yyyy-MM-dd')

INSERT /*+ append */ INTO ${newTableName}
SELECT /*+ parallel(SUB,8) */ sub.* FROM  CHB_INVESTHOLD_INFO_SUB SUB
WHERE SUB.HOLD_DATE BETWEEN TO_DATE(#{startDate,jdbcType=VARCHAR},'yyyy-MM-dd') AND TO_DATE(#{endDate,jdbcType=VARCHAR},'yyyy-MM-dd')
